import { chromium } from "playwright-core";
import http from "node:http";
import fs from "node:fs";
import path from "node:path";

const root = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const chrome = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, F: [], S: [] }],
  };
}

const p0 = [0, 0];
const p1 = [2, 1];
const p2 = [4, 0];
const ndjson = [
  {
    type: "header",
    eps: 0.9,
    delta: 500,
    grid_val: 12.5,
    r_val: 8.2,
    expected_frechet: 1.25,
    bbox: [-1, -1, 6, 3],
    stream: [p0, p1, p2],
  },
  {
    type: "prefix",
    data: {
      start_idx: 0,
      end_idx: 2,
      p0_idx: 0,
      p0,
      P: [[0.2, 0.2], [0.3, -0.1]],
      output: [p0, p2],
      steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
    },
  },
  { type: "done", time_ms: 12.4, simplified: [p0, p2], frechet_distance: 0.41 },
].map((o) => JSON.stringify(o)).join("\n") + "\n";

function mime(filePath) {
  if (filePath.endsWith(".js")) return "text/javascript";
  if (filePath.endsWith(".css")) return "text/css";
  if (filePath.endsWith(".html")) return "text/html";
  if (filePath.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, n_points: 3, label: "Demo" }] }));
    return;
  }
  if (url.pathname.startsWith("/api/trace")) {
    res.writeHead(200, { "Content-Type": "application/x-ndjson" });
    res.end(ndjson);
    return;
  }
  if (url.pathname === "/api/frechet") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ distance: 0.4123 }));
    return;
  }
  const filePath = url.pathname === "/"
    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });

async function loadTrace(page) {
  await page.waitForFunction(() => {
    const sel = document.getElementById("traceSelect");
    return sel && [...sel.options].some((o) => o.value === "1");
  }, { timeout: 8000 });
  await page.selectOption("#traceSelect", "1");
  await page.click("#loadBtn");
  await page.waitForFunction(() => document.body.classList.contains("playback-ready"), { timeout: 8000 });
  await page.waitForTimeout(400);
  try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
  await page.waitForTimeout(400);
}

function measureAll(page) {
  return page.evaluate(() => {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const header = document.querySelector("header");
    const params = document.getElementById("paramsBar");
    const sidebar = document.getElementById("sidebar");
    const playback = document.getElementById("playbackBar");
    const row = document.getElementById("toggle-S")?.closest(".toggle-row");
    const label = row?.querySelector("label");
    const sr = sidebar.getBoundingClientRect();
    const lr = label?.getBoundingClientRect();
    const hr = header.getBoundingClientRect();
    const pr = params.getBoundingClientRect();
    const pbr = playback.getBoundingClientRect();
    const mj = [...(row?.querySelectorAll("mjx-container") || [])].map((n) => {
      const r = n.getBoundingClientRect();
      return {
        text: n.textContent?.slice(0, 40),
        x: Math.round(r.x),
        w: Math.round(r.width),
        right: Math.round(r.x + r.width),
        y: Math.round(r.y),
      };
    });
    const overflowNodes = [];
    const walk = (el) => {
      if (!(el instanceof Element)) return;
      const r = el.getBoundingClientRect();
      if (r.width > 2 && r.right > vw + 1) {
        overflowNodes.push({
          id: el.id,
          tag: el.tagName.toLowerCase(),
          cls: el.className?.toString?.().slice(0, 60),
          right: Math.round(r.right),
          w: Math.round(r.width),
        });
      }
      for (const c of el.children) walk(c);
    };
    walk(document.body);

    const pbKids = [...playback.querySelectorAll("button, input, span")].map((n) => {
      const r = n.getBoundingClientRect();
      const vis = getComputedStyle(n).visibility;
      const disp = getComputedStyle(n).display;
      return {
        id: n.id || n.textContent?.trim().slice(0, 18),
        x: Math.round(r.x),
        y: Math.round(r.y),
        w: Math.round(r.width),
        h: Math.round(r.height),
        right: Math.round(r.right),
        bottom: Math.round(r.bottom),
        clippedX: r.right > vw + 1 || r.left < -1,
        clippedY: r.bottom > vh + 1,
        vis,
        disp,
      };
    });

    return {
      vw,
      vh,
      scrollW: document.documentElement.scrollWidth,
      pageOverflowX: document.documentElement.scrollWidth > vw + 1,
      headerH: Math.round(hr.height),
      paramsH: Math.round(pr.height),
      paramsW: Math.round(pr.width),
      paramsText: params.innerText.replace(/\s+/g, " ").slice(0, 220),
      sidebar: { x: Math.round(sr.x), w: Math.round(sr.width), right: Math.round(sr.right) },
      label: label ? {
        x: Math.round(lr.x),
        w: Math.round(lr.width),
        right: Math.round(lr.right),
        sw: label.scrollWidth,
        cw: label.clientWidth,
      } : null,
      mj,
      mjPastSidebar: mj.some((m) => m.right > sr.right + 1),
      mjPastViewport: mj.some((m) => m.right > vw + 1),
      playback: {
        h: Math.round(pbr.height),
        w: Math.round(pbr.width),
        y: Math.round(pbr.y),
        display: getComputedStyle(playback).display,
        wrap: getComputedStyle(playback).flexWrap,
      },
      overflowNodes: overflowNodes.slice(0, 20),
      pbClipped: pbKids.filter((k) => k.clippedX || k.clippedY || (k.w === 0 && k.disp !== "none")),
      pbKids: pbKids.filter((k) => k.disp !== "none").slice(0, 30),
    };
  });
}

const out = {};
try {
  for (const [name, width, height] of [
    ["live900", 900, 700],
    ["live1024", 1024, 700],
    ["live1280", 1280, 800],
  ]) {
    const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
    await page.goto(origin, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    if (width <= 720) {
      try { await page.click("#mobileLayersToggle"); } catch {}
    }
    await page.evaluate(() => document.getElementById("layersSection")?.scrollIntoView({ block: "center" }));
    await page.waitForTimeout(200);
    out[name] = await measureAll(page);
    await page.screenshot({ path: `/tmp/pwshot/${name}.png` });
    await page.close();
  }

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await mobile.goto(origin, { waitUntil: "domcontentloaded" });
  await loadTrace(mobile);
  await mobile.click("#mobileLayersToggle");
  await mobile.waitForTimeout(300);
  try { await mobile.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
  await mobile.evaluate(() => document.getElementById("layersSection")?.scrollIntoView({ block: "center" }));
  await mobile.waitForTimeout(200);
  out.mobile390 = await measureAll(mobile);
  await mobile.screenshot({ path: "/tmp/pwshot/mobile390.png" });
  await mobile.close();

  fs.writeFileSync("/tmp/pwshot/audit-iter18.json", JSON.stringify(out, null, 2));
  console.log(JSON.stringify(out, null, 2));
} finally {
  await browser.close();
  server.close();
}

