    ? path.join(root, "index.html")
    : path.join(root, url.pathname.replace(/^\//, ""));
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end("not found");
      return;
    }
    res.writeHead(200, { "Content-Type": mime(filePath) });
    res.end(data);
  });
});

function flushTrace() {
  const res = pending.shift();
  if (!res) return;
  res.writeHead(200, { "Content-Type": "application/x-ndjson" });
  res.end(ndjson);
}

function measure(page) {
  return page.evaluate(() => {
    const header = document.querySelector("header");
    const params = document.getElementById("paramsBar");
    const kids = [...params.children].map((c) => {
      const r = c.getBoundingClientRect();
      return {
        text: (c.innerText || "").replace(/\s+/g, " ").trim().slice(0, 40),
        y: Math.round(r.y),
        x: Math.round(r.x),
      };
    });
    const rows = [...new Set(kids.map((k) => k.y))];
    return {
      vw: window.innerWidth,
      headerH: Math.round(header.getBoundingClientRect().height),
      paramsH: Math.round(params.getBoundingClientRect().height),
      paramsText: params.innerText.replace(/\s+/g, " ").trim(),
      chipCount: kids.length,
      rowCount: rows.length,
      hasSpinner: !!params.querySelector(".params-spinner"),
      hud: document.getElementById("traceLoadingHud")?.classList.contains("visible"),
    };
  });
}

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ executablePath: chrome, headless: true });
const out = {};

try {
  const fixture = await browser.newPage({ viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 });
  await fixture.goto(pathToFileURL(path.join(usability, "desktop-loading-params-wrap.html")).href, {
    waitUntil: "domcontentloaded",
  });
  await fixture.evaluate((script) => { eval(script); }, freezeSpinners);
  await fixture.screenshot({ path: path.join(usability, "desktop-loading-params-wrap.png"), fullPage: true });
  await fixture.close();

  async function capturePair(width, height, loadingPath, loadedPath, key) {
    const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
    await page.goto(origin, { waitUntil: "domcontentloaded" });
    await page.waitForFunction(() => [...document.getElementById("traceSelect").options].some((o) => o.value === "1"));
    await page.evaluate((script) => { eval(script); }, freezeSpinners);
    await page.selectOption("#traceSelect", "1");
    await page.click("#loadBtn");
    await page.waitForSelector("#traceLoadingHud.visible");
    await page.waitForTimeout(500);
    try { await page.evaluate(() => window.MathJax?.typesetPromise?.([document.getElementById("paramsBar")])); } catch {}
    await page.waitForTimeout(400);
    out[`${key}Loading`] = await measure(page);
    await page.screenshot({ path: loadingPath });
    flushTrace();
    await page.waitForFunction(() => document.body.classList.contains("playback-ready"), { timeout: 8000 });
    await page.waitForTimeout(600);
    try { await page.evaluate(() => window.MathJax?.typesetPromise?.([document.getElementById("paramsBar")])); } catch {}
    await page.waitForTimeout(400);
    out[`${key}Loaded`] = await measure(page);
    if (loadedPath) await page.screenshot({ path: loadedPath });
    await page.close();
  }

  await capturePair(
    1280,
    800,
    path.join(usability, "desktop-loading-params-wrap-live.png"),
    path.join(usability, "desktop-loading-params-wrap-loaded-live.png"),
    "w1280",
  );
  await capturePair(
    900,
    700,
    path.join(usability, "desktop-loading-params-wrap-900-live.png"),
    path.join(usability, "desktop-loading-params-wrap-900-loaded-live.png"),
    "w900",
  );

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
  await mobile.goto(origin, { waitUntil: "domcontentloaded" });
  await mobile.waitForFunction(() => [...document.getElementById("traceSelect").options].some((o) => o.value === "1"));
  await mobile.evaluate((script) => { eval(script); }, freezeSpinners);
  await mobile.selectOption("#traceSelect", "1");
  await mobile.click("#loadBtn");
  await mobile.waitForSelector("#traceLoadingHud.visible");
  await mobile.waitForTimeout(400);
  out.mobileLoading = await measure(mobile);
  await mobile.screenshot({ path: path.join(usability, "mobile-loading-params-wrap-regression-live.png") });
  flushTrace();
  await mobile.close();

  fs.writeFileSync("/tmp/pwshot/params-wrap-metrics.json", JSON.stringify(out, null, 2));
  console.log(JSON.stringify(out, null, 2));
} finally {
  await browser.close();
  server.close();
}
